        DatasetFilePath filePath = (ReadOnlySpan<byte> key, ulong index, IParquetBufferPool pool, out ParquetBuffer? allocation) =>
            RandomDatasetKeys.FilePath(key, index, out allocation);
        return new Sink(createParts ? Rnd819v.CreateDatasetWriter(route, filePath, files, options)
            : Rnd819v.CreateDatasetWriter(route, files, options));
    }

    sealed class Sink(Rnd819v.DatasetWriter writer) : IRandomDatasetSink
    {
        public void Queue(object row) => writer.Queue((Rnd819v)row);
        public void Dispose() => writer.Dispose();
    }
}